// The answer page once joined: decrypt and check each batch from the agent, then show it.
import { open, type Keys } from "../../shared/crypto";
import { app, h } from "../dom";
import { render, type Batch, type Open, type Say } from "../form/render";
// @ts-ignore generated by build.ts
import { question as validQuestion, say as validSay } from "../gen/validate.js";
import { batchName, clock, event, home, live, nameSession, ping, say, sessName, startNew, status, toFeed } from "../page";
import type { Question } from "../types";
import { send } from "./send";
import { drop, save, type State } from "./storage";

export function listen(sid: string, keys: Keys, st: State) {
  status("wait", "Connected", "Waiting for the agent's question. This page updates by itself, keep it open.");
  const es = new EventSource(`/s/${sid}/q`);
  const born = Date.now(); // batches in the first moments are replays after a reload: no ping
  if (!st.start) { st.start = born; save(sid, st); }
  clock(st.start);
  let cur: Open | null = null;
  let later: Batch[] = []; // arrived while an answer was being sent: placed once it's done
  let chain: Promise<unknown> = Promise.resolve(); // decrypting and placing are async: keep batches in order
  const queue = (fn: () => Promise<unknown>) => { chain = chain.then(fn).catch(console.error); };
  const done = () => queue(async () => {
    if (cur?.sending || !cur?.f.form.isConnected) cur = null; // everything was sent or timed out; otherwise the form is still open
    const b = later;
    later = [];
    for (const [s, q] of b) await place(s, q);
  });
  // Why a batch can't join the open form. The agent client checks the same, this only guards the merged answer.
  const clash = (f: Open["f"], q: Question) => {
    const have = new Set(f.fields.map((x) => x.it.id));
    const dup = q.questions.filter((x) => have.has(x.id)).map((x) => x.id);
    return dup.length ? `ids already in the open form: ${dup.join(", ")}` : f.fields.length + q.questions.length > 50 ? "the open form would have more than 50 questions" : null;
  };
  const onQ = async (seq: number, data: string) => {
    let q: Question | Say;
    try {
      q = JSON.parse(await open(keys, sid, "q", seq, JSON.parse(data)));
    } catch {
      const msg = "A message from the agent failed verification and was ignored. If this repeats, ask the agent for a new link.";
      if (cur) { cur.f.err.textContent = msg; return; } // keep what the user has typed
      return status("error", "A message failed verification", "It was ignored. If this repeats, ask the agent for a new link.");
    }
    await place(seq, q);
  };
  const place = async (seq: number, q: Question | Say) => {
    if ("say" in q) return void (validSay(q) && say(q.say)); // never answered; a bad one is just dropped
    const ok = validQuestion(q);
    if (ok && (q.name || (!sessName.textContent && q.title))) nameSession(q.name ?? q.title!); // no name yet: the first title will do
    if (st.answered.includes(seq)) return void (ok && toFeed(event("check", `Answered: ${batchName(q)}`))); // replayed after a reload
    if (cur?.sending) return void later.push([seq, q]);
    const target = cur;
    const problem = !validQuestion(q) ? (validQuestion as any).errors?.map((x: any) => `${x.instancePath || "/"} ${x.message}`).join("; ") ?? "invalid"
      : target ? clash(target.f, q) : null;
    if (problem) {
      // the batch is dropped; an open form stays as it is
      await send(sid, keys, st, [seq], { seqs: [seq], answers: {}, skipped: [], comments: {}, note: "", error: `invalid question: ${problem}`.slice(0, 2000) }).catch(() => {});
      if (cur) return;
      return status("error", "This question can't be shown", "The agent sent a form this page doesn't understand. It has been told; wait for a corrected one.", live("Waiting for the agent…"));
    }
    if (cur) cur.add([seq, q]);
    else cur = render(sid, keys, st, [[seq, q]], done);
    if (Date.now() - born > 1500) ping(q.mood);
  };
  es.addEventListener("q", (e) => queue(() => onQ(Number(e.lastEventId), e.data)));
  es.addEventListener("close", () => {
    es.close();
    drop(sid);
    status("done", "Session ended", "The agent closed this session and the relay deleted it. You can close this tab.",
      h("div", { className: "state-actions" }, startNew("btn-primary"), home()));
  });
  es.onerror = () => {
    if (es.readyState === EventSource.CLOSED) return status("error", "This session has ended or expired", undefined, startNew(), home());
    // the browser reconnects by itself; say so instead of a "Connected" that isn't
    const l = app.querySelector(".live");
    if (l?.lastChild && l.lastChild.textContent !== "Reconnecting…") {
      const was = l.lastChild.textContent;
      l.lastChild.textContent = "Reconnecting…";
      es.addEventListener("open", () => (l.lastChild!.textContent = was), { once: true });
    }
  };
}
